SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, CASE WHEN humidity >= 80 THEN 'HIGH' ELSE 'LOW' END AS humidity_tier, ROUND(SUM(temp_c) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS temp_c_per_dv_04, APPROX_PERCENTILE(status_bits, 0.5) AS status_bits_p50, COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END) AS dv_02_count, COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END) AS dv_04_count, GROUPING_ID() AS gid FROM device_readings GROUP BY GROUPING SETS ((DATE_TRUNC('DAY', reading_ts), CASE WHEN humidity >= 80 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('DAY', reading_ts))) ORDER BY activity_day DESC;
